20	import { bind, each, isFunction, isString, indexOf } from 'zrender/src/core/util';
21	import * as eventTool from 'zrender/src/core/event';
22	import * as graphic from '../../util/graphic';
23	import * as throttle from '../../util/throttle';
24	import DataZoomView from './DataZoomView';
25	import { linearMap, asc, parsePercent } from '../../util/number';
26	import * as layout from '../../util/layout';
27	import sliderMove from '../helper/sliderMove';
28	import GlobalModel from '../../model/Global';
29	import ExtensionAPI from '../../core/ExtensionAPI';
30	import {
31	    LayoutOrient, Payload, ZRTextVerticalAlign, ZRTextAlign, ZRElementEvent, ParsedValue
32	} from '../../util/types';
33	import SliderZoomModel from './SliderZoomModel';
34	import { RectLike } from 'zrender/src/core/BoundingRect';
35	import Axis from '../../coord/Axis';
36	import SeriesModel from '../../model/Series';
37	import { AxisBaseModel } from '../../coord/AxisBaseModel';
38	import { getAxisMainType, collectReferCoordSysModelInfo } from './helper';
39	import { enableHoverEmphasis } from '../../util/states';
40	import { createSymbol, symbolBuildProxies } from '../../util/symbol';
41	import { deprecateLog } from '../../util/log';
42	import { PointLike } from 'zrender/src/core/Point';
